#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=9

# All values land in an ignored env file at the repo root; nothing is committed.
cd "$(dirname "${BASH_SOURCE[0]}")/.."
ENV_FILE=".env.hosted-slm.local"
IMAGE="ghcr.io/basic-bit/discord-time-app-temporal-ir-qwen35-hosted:v22"
MODEL_ID="qwen-temporal-ir-qwen35-08b-bf16-chat-range-format-infix-v22"

banner "Hosted SLM: RunPod Serverless load-balancing endpoint for V22"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Hygiene: rotate the Hugging Face token exposed in June"
say "The June RunPod edit UI showed an HF token in clear text. Nothing in this"
say "setup needs an HF token (the adapter comes from the GitHub release, the base"
say "model is public), so rotating it is pure hygiene."
open_url "https://huggingface.co/settings/tokens"
step "Find the token used for the RunPod endpoint in June."
step "Delete it. Create a new one only if some other workflow still needs it."
pause "Done? Press Enter."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Publish the hosted model image to GHCR"
say "Image: $IMAGE"
say "It is self-contained: V22 adapter, base weights, /ping health route."
if docker image inspect "$IMAGE" >/dev/null 2>&1; then
  note "already built locally"
else
  say "Not built yet. Building takes a few minutes (downloads the adapter and base model)."
  if confirm "Build it now?"; then
    docker build -f docker/temporal-ir-qwen35-hosted.Dockerfile -t "$IMAGE" .
  fi
fi
say "Pushing publishes the image under ghcr.io/basic-bit (the package is public,"
say "like the existing local runtime image). You need a GitHub token with"
say "write:packages: either 'gh auth refresh -s write:packages' first, or a PAT."
if confirm "Log in to ghcr.io and push $IMAGE now?"; then
  if gh auth token >/dev/null 2>&1; then
    gh auth token | docker login ghcr.io -u BASIC-BIT --password-stdin
  else
    docker login ghcr.io -u BASIC-BIT
  fi
  docker push "$IMAGE"
  note "if the push was denied, run: gh auth refresh -s write:packages, then re-run this stage"
else
  SKIPPED+=("docker push $IMAGE")
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "RunPod: create the Serverless load-balancing endpoint"
open_url "https://console.runpod.io/serverless"
step "New Endpoint → Import from Docker Registry."
step "Container image: $IMAGE   (public, no registry credentials)"
step "Endpoint type: Load balancer (NOT queue). Name: hammer-temporal-v22"
step "GPU: the 16 GB tier (RTX A4000 / RTX 4000 Ada class). bf16 needs Ampere or newer; avoid T4."
step "Workers: Active 0, Max 1.  Idle timeout: 300 seconds (must stay above the app's 240 s ready window)."
step "FlashBoot: on.  Container disk: 30 GB."
step "Storage → attach a Network Volume (create one first: Storage → New, 5 GB, same region/datacenter as the endpoint)."
step "   It persists compiled GPU kernels across workers; without it every fresh worker re-compiles for ~3 minutes."
step "Environment variables: PORT=8770, PORT_HEALTH=8770  (RunPod polls GET /ping on PORT_HEALTH),"
step "   TRITON_CACHE_DIR=/runpod-volume/triton-cache, TEMPORAL_IR_PREWARM=1."
step "Leave execution timeout at its default. Create the endpoint."
step "Copy the Endpoint ID from the endpoint page header."
ask HOSTED_SLM_ENDPOINT_ID "Paste the Endpoint ID:"
HOSTED_SLM_BASE_URL="https://${HOSTED_SLM_ENDPOINT_ID}.api.runpod.ai/v1"
write_env HOSTED_SLM_ENDPOINT_ID "$HOSTED_SLM_ENDPOINT_ID"
write_env HOSTED_SLM_BASE_URL "$HOSTED_SLM_BASE_URL"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "RunPod: create a restricted API key for the app"
say "This key ships inside the desktop binary later, so it must be able to do"
say "nothing except call this one endpoint."
open_url "https://console.runpod.io/user/settings"
step "API Keys → Create API Key. Name: hammer-overlay-client"
step "Permissions: Restricted. Grant access ONLY to the endpoint hammer-temporal-v22 (no account read/write)."
step "Copy the key; it is shown once."
ask_secret RUNPOD_API_KEY "Paste the key:"
write_env RUNPOD_API_KEY "$RUNPOD_API_KEY"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "RunPod: spend limit"
open_url "https://console.runpod.io/user/billing"
step "Set a spending limit or low-balance alert. Expected: about \$10/month at June usage;"
step "\$50/month is the product cap. One worker at the flex rate pinned 24/7 would be about \$420."
pause "Done? Press Enter."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Verify the endpoint through the gateway"
say "First call wakes a worker: expect 30 to 120 s. The gateway returns"
say "'no workers available' until it is up, so this retries every 10 s for 3 minutes."
ok=""
for i in $(seq 1 18); do
  if out=$(curl -sS --max-time 20 -H "Authorization: Bearer $RUNPOD_API_KEY" "https://${HOSTED_SLM_ENDPOINT_ID}.api.runpod.ai/ping" 2>&1) && [[ "$out" == *healthy* ]]; then
    ok=1; break
  fi
  note "attempt $i: ${out:0:120}"
  sleep 10
done
if [[ -n "$ok" ]]; then
  printf '  %s✓ /ping%s %s\n' "$GREEN" "$RESET" "$out"
  models=$(curl -sS --max-time 30 -H "Authorization: Bearer $RUNPOD_API_KEY" "$HOSTED_SLM_BASE_URL/models")
  if [[ "$models" == *"$MODEL_ID"* ]]; then
    printf '  %s✓ /v1/models serves%s %s\n' "$GREEN" "$RESET" "$MODEL_ID"
  else
    warn "unexpected /v1/models body: ${models:0:300}"
  fi
else
  warn "endpoint never became healthy. Check the worker logs in the RunPod console (PORT/PORT_HEALTH, image pull)."
  SKIPPED+=("endpoint verification (stage 6)")
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Eval gate against the hosted endpoint"
say "Runs the production routing boundary: 197/197 required routed cases and"
say "159/159 model-owned cases must pass. Takes 10 to 20 minutes and a few cents."
say "Cost projection uses \$0.01 per call at 1000 requests/month (= \$10, under the \$50 cap)."
if confirm "Run the eval gate now?"; then
  mkdir -p reports/temporal-ml
  TEMPORAL_MODEL_FIXED_USD_PER_CALL=0.01 \
  powershell -NoProfile -ExecutionPolicy Bypass -File scripts/run-temporal-evaluation-boundary.ps1 \
    -EndpointBaseUrl "$HOSTED_SLM_BASE_URL" -ApiKey "$RUNPOD_API_KEY" \
    -DeploymentMode hosted -MonthlyRequests 1000 -EndpointTimeoutMs 120000 \
    -Output "reports/temporal-ml/hosted-v22-runpod-lb-boundary.json" \
    && printf '  %s✓ eval gate passed%s\n' "$GREEN" "$RESET" \
    || { warn "eval gate FAILED. Do not flip the release defaults. Report: reports/temporal-ml/hosted-v22-runpod-lb-boundary.json"; SKIPPED+=("eval gate (stage 7) failed"); }
else
  SKIPPED+=("eval gate (stage 7)")
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Arm the daily probe (the alarm)"
say ".github/workflows/hosted-slm-probe.yml calls /v1/models once a day and GitHub"
say "emails you when it fails. It wakes the worker once a day (about 3 cents)."
if confirm "Set the GitHub secret HOSTED_SLM_API_KEY and variable HOSTED_SLM_BASE_URL now?"; then
  set_secret HOSTED_SLM_API_KEY "$RUNPOD_API_KEY"
  set_var HOSTED_SLM_BASE_URL "$HOSTED_SLM_BASE_URL"
  if confirm "Trigger the probe once now to prove the alarm path?"; then
    gh workflow run hosted-slm-probe.yml && note "watch it: gh run list --workflow hosted-slm-probe.yml"
  fi
else
  SKIPPED+=("GitHub secret HOSTED_SLM_API_KEY and variable HOSTED_SLM_BASE_URL")
fi
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Release flip"
say "Everything the app needs is now in $ENV_FILE:"
say "  HOSTED_SLM_BASE_URL=$HOSTED_SLM_BASE_URL"
say "  RUNPOD_API_KEY=(hidden)"
say "The release that turns hosted on fills HOSTED_SLM_DEFAULT_ENDPOINT_BASE_URL and"
say "HOSTED_SLM_DEFAULT_API_KEY in src-tauri/src/lib.rs, flips the slm_mode default to"
say "hosted and local_slm_enabled to true, and mirrors the two defaults in"
say "src/components/Settings.tsx. Hand that to Claude with: 'flip the hosted defaults"
say "from .env.hosted-slm.local' and it opens the PR."
pause "Press Enter to finish."

finish
